+++ b/tmp/sv-adce7e929d004b8eb2ad35e20b531900/Components/Pages/Board/Board.razor
@@ -1,0 +1,140 @@
+@page "/board"
+@using sv_adce7e929d004b8eb2ad35e20b531900.Services
+@inject ITaskService TaskService
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h1>Kanban Board</h1>
+
+@if (isLoading)
+{
+    <p class="board-loading">Loading tasks…</p>
+}
+else if (errorMessage is not null)
+{
+    <div class="board-error">
+        <p>@errorMessage</p>
+        <button @onclick="LoadTasks">Retry</button>
+    </div>
+}
+else
+{
+    <BoardStatsBar Tasks="allTasks" />
+    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchTextChanged" />
+
+    <div class="board-columns">
+        <BoardColumn Title="To Do"
+                     Status="To Do"
+                     Tasks="GetFilteredTasks("To Do")"
+                     ShowMoveLeft="false"
+                     ShowMoveRight="true"
+                     OnMoveRight="task => MoveTask(task, "In Progress")"
+                     OnTaskCreated="CreateTask"
+                     IsMoving="isMoving" />
+
+        <BoardColumn Title="In Progress"
+                     Status="In Progress"
+                     Tasks="GetFilteredTasks("In Progress")"
+                     ShowMoveLeft="true"
+                     ShowMoveRight="true"
+                     OnMoveLeft="task => MoveTask(task, "To Do")"
+                     OnMoveRight="task => MoveTask(task, "Done")"
+                     OnTaskCreated="CreateTask"
+                     IsMoving="isMoving" />
+
+        <BoardColumn Title="Done"
+                     Status="Done"
+                     Tasks="GetFilteredTasks("Done")"
+                     ShowMoveLeft="true"
+                     ShowMoveRight="false"
+                     OnMoveLeft="task => MoveTask(task, "In Progress")"
+                     OnTaskCreated="CreateTask"
+                     IsMoving="isMoving" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private string searchText = string.Empty;
+    private bool isLoading = true;
+    private bool isMoving;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        isLoading = true;
+        errorMessage = null;
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void OnSearchTextChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        var tasks = allTasks.Where(t => t.Status == status);
+
+        if (!string.IsNullOrWhiteSpace(searchText))
+        {
+            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
+        }
+
+        return tasks.ToList();
+    }
+
+    private async Task MoveTask(TaskItem task, string newStatus)
+    {
+        isMoving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            var index = allTasks.FindIndex(t => t.Id == task.Id);
+            if (index >= 0)
+            {
+                allTasks[index] = task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+        finally
+        {
+            isMoving = false;
+        }
+    }
+
+    private async Task CreateTask(TaskItem formData)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(
+                formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
+            allTasks.Add(created);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
+

toolArgs.file_text:
/* Stats bar */
.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search bar */
.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* Board layout */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 0.75rem;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    margin: 0 0 0.5rem;
    font-size: 1.1rem;
}

.column-count {
    color: #6c757d;
    font-weight: 400;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 60px;
}

.column-footer {
    margin-top: 0.75rem;
}

/* Task card */
.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.4rem;
    font-size: 0.85rem;
    color: #495057;
}

.task-due {
    font-size: 0.8rem;
    color: #6c757d;
    margin-left: 0.5rem;
}

/* Priority badges */
.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

/* Move buttons */
.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.4rem;
}

.btn-move {
    padding: 0.2rem 0.5rem;
    font-size: 0.8rem;
    border: 1px solid #adb5bd;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-move:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Add task form */
.btn-add-task {
    width: 100%;
    padding: 0.4rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    color: #6c757d;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-save {
    padding: 0.3rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-save:disabled {
    opacity: 0.6;
}

.btn-cancel {
    padding: 0.3rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel:disabled {
    opacity: 0.6;
}

.form-error {
    color: #dc3545;
    font-size: 0.8rem;
    margin: 0;
}

/* Loading / error states */
.board-loading {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc3545;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.3rem 1rem;
    border: 1px solid #dc3545;
    border-radius: 4px;
    background: #fff;
    color: #dc3545;
    cursor: pointer;
}

